import {test} from 'node:test'
import assert from 'node:assert/strict'
import * as T from 'three'
import {readRig} from '../scripts/check-animation.js'
import {attachSpiderAnimation} from '../src/spider-model.js'

test('Blender export has distinct looping walking and turning skin motion',async()=>{
  const {scene,animations}=await readRig()
  const snapshot=()=>{
    scene.updateMatrixWorld(true);const values=[]
    scene.traverse(m=>{if(m.isSkinnedMesh){m.skeleton.update();for(let i=0;i<m.geometry.attributes.position.count;i+=137)values.push(...m.getVertexPosition(i,new T.Vector3()).toArray())}})
    return values
  }
  const poses=[]
  for(const name of ['Walk','TurnLeft','TurnRight']) {
    const clip=animations.find(c=>c.name===name);assert.ok(clip,`${name} exists`)
    const mixer=new T.AnimationMixer(scene),action=mixer.clipAction(clip).play()
    mixer.update(0);const first=snapshot();mixer.update(.37);const next=snapshot()
    assert.ok(first.some((v,i)=>Math.abs(v-next[i])>1e-4),`${name} deforms vertices`)
    mixer.setTime(clip.duration-.00001);const last=snapshot()
    assert.ok(first.every((v,i)=>Math.abs(v-last[i])<.001),`${name} closes the loop`)
    poses.push(next);action.stop();mixer.uncacheRoot(scene)
  }
  assert.ok(poses[1].some((v,i)=>Math.abs(v-poses[2][i])>.001),'opposite turns differ')
  const mixer=new T.AnimationMixer(scene),idle=mixer.clipAction(animations.find(c=>c.name==='Spider_default.005'))
  const player=new T.Group();attachSpiderAnimation(player,mixer,idle,null,animations)
  player.userData.updateAnimation(.4,true,false,{speed:1,forward:-1})
  assert.ok(mixer.clipAction(animations.find(c=>c.name==='Walk')).timeScale<0,'backwards reverses gait')
  player.userData.updateAnimation(.4,false,false,{turn:3})
  assert.ok(mixer.clipAction(animations.find(c=>c.name==='TurnLeft')).getEffectiveWeight()>.9)
  player.userData.updateAnimation(.4,false,false,{turn:-3})
  assert.ok(mixer.clipAction(animations.find(c=>c.name==='TurnRight')).getEffectiveWeight()>.9)
  const pose=snapshot();player.userData.updateAnimation(1,true,true,{turn:3})
  assert.deepEqual(snapshot(),pose,'pause freezes all blended clips')
  player.userData.resetAnimation()
  assert.equal(idle.getEffectiveWeight(),1)
})
